0B1' + itemTotal(item).toFixed(2)"></span></div><input type="hidden" :name="'items[' + index + '][product_id]'" :value="item.product_id"><input type="hidden" :name="'items[' + index + '][quantity]'" :value="item.quantity"><input type="hidden" :name="'items[' + index + '][container_type]'" :value="item.container_type || ''"></div></template><div class="flex items-center justify-between pt-2 text-sm"><span>Items subtotal</span><span class="font-mono" x-text="'₱' + subtotal.toFixed(2)"></span></div><div class="flex items-center justify-between text-sm"><span>Delivery fee (<span x-text="gallonCount"></span> <span x-text="gallonCount === 1 ? 'gallon' : 'gallons'"></span> × ₱<span x-text="feeRate.toFixed(2)"></span>)</span><span class="font-mono" x-text="'₱' + deliveryFee.toFixed(2)"></span></div><div class="flex items-center justify-between border-t border-slate-100 pt-2 text-base font-bold dark:border-white/10"><span>Total</span><span class="font-mono text-primary-600" x-text="'\u20B1' + total.toFixed(2)"></span></div></div><div class="mt-5 space-y-4 border-t border-slate-100 pt-5 dark:border-white/10"><fieldset><legend class="text-sm font-medium text-slate-700 dark:text-slate-200">Payment method</legend><p class="mt-1 text-xs text-slate-400">Choose how you will pay for this delivery.</p><div class="mt-3 grid gap-2"><label class="flex cursor-pointer items-center gap-3 rounded-xl border border-slate-200 p-3 has-[:checked]:border-primary-500 has-[:checked]:bg-primary-50 dark:border-white/10 dark:has-[:checked]:border-primary-400 dark:has-[:checked]:bg-primary-500/10"><input type="radio" name="payment_method" value="cash" @checked(old('payment_method', 'cash') === 'cash') class="border-slate-300 text-primary-600 focus:ring-primary-600"><span><span class="block text-sm font-semibold text-slate-900 dark:text-white">Cash</span><span class="text-xs text-slate-500">Pay when your order is delivered.</span></span></label><label class="flex cursor-pointer items-center gap-3 rounded-xl border border-slate-200 p-3 has-[:checked]:border-primary-500 has-[:checked]:bg-primary-50 dark:border-white/10 dark:has-[:checked]:border-primary-400 dark:has-[:checked]:bg-primary-500/10"><input type="radio" name="payment_method" value="loan" @checked(old('payment_method') === 'loan') class="border-slate-300 text-primary-600 focus:ring-primary-600"><span><span class="block text-sm font-semibold text-slate-900 dark:text-white">Credit</span><span class="text-xs text-slate-500">Added to your account balance; payment is due within 14 days.</span></span></label></div></fieldset><div><x-input-label for="customer_address" value="Delivery Address (Required)" /><x-textarea id="customer_address" name="customer_address" class="mt-1" maxlength="2000" aria-required="true" aria-describedby="delivery-address-help" placeholder="House number, street, barangay, and city / municipality" required>{{ old('customer_address', auth()->user()->address) }}</x-textarea><p id="delivery-address-help" class="mt-1 text-xs text-slate-500">Enter the complete address where your order will be delivered.</p><x-input-error :messages="$errors->get('customer_address')" class="mt-1" /></div><div><x-input-label for="preferred_delivery_date" value="Preferred delivery date (optional)" /><x-text-input id="preferred_delivery_date" type="date" name="preferred_delivery_date" class="mt-1" :value="old('preferred_delivery_date')" data-flatpickr /></div><div><x-input-label for="notes" value="Order notes (optional)" /><x-textarea id="notes" name="notes" class="mt-1">{{ old('notes') }}</x-textarea></div><p class="rounded-lg bg-primary-50 p-3 text-sm text-primary-800 dark:bg-primary-500/10 dark:text-primary-200">Please review your items and delivery address. Once placed, you cannot cancel this order.</p><x-button type="submit" class="w-full" x-bind:disabled="cart.length === 0 || confirming || submitting"><span x-text="submitting ? 'Placing Order...' : 'Place Order'">Place Order</span></x-button></div></x-card></