    @push('scripts')<script>function customerOrder(products, oldItems, feeRate) { return { products, feeRate: Number(feeRate || 0), search: '', containerType: 'round', confirming: false, submitting: false,
        async confirmOrder(form) {
            if (this.confirming || this.submitting || this.cart.length === 0 || !form.reportValidity()) return;
            this.confirming = true;
            try {
                const result = await window.Swal.fire({
                    title: 'Confirm Your Order',
                    text: 'Your order total is PHP ' + this.total.toFixed(2) + '. Please check your items and delivery address. Once placed, you cannot cancel this order.',
                    icon: 'question', showCancelButton: true,
                    confirmButtonText: 'Confirm and Place Order', cancelButtonText: 'Review Order',
                    confirmButtonColor: '#0369a1', cancelButtonColor: '#64748b',
                    focusCancel: true, reverseButtons: true,
                });
                if (result.isConfirmed && form.reportValidity()) {
                    this.submitting = true;
                    HTMLFormElement.prototype.submit.call(form);
                }
            } finally { this.confirming = false; }
        }, cart: oldItems.length ? oldItems.map(item => { const p = products.find(product => String(product.id) === String(item.product_id)); return p ? { ...p, product_id: p.id, quantity: Number(item.quantity || 1), container_type: item.container_type || (p.requires_container_choice ? 'round' : null) } : null; }).filter(Boolean) : [], get filteredProducts() { const term = this.search.toLowerCase(); return this.products.filter(p => !term || (p.name + ' ' + p.size).toLowerCase().includes(term)); }, containerLabel(type) { return type === 'slim' ? 'Slim Gallon' : 'Round Gallon'; }, stockFor(product, type = this.containerType) { return Number(product.requires_container_choice ? product[type + '_stock'] || 0 : product.stock_quantity); }, cartQuantity(id, type) { return this.cart.filter(item => item.product_id === id && (item.container_type || null) === (type || null)).reduce((sum, item) => sum + item.quantity, 0); }, addToCart(product) { if (this.cartQuantity(product.id, product.requires_container_choice ? this.containerType : null) >= this.stockFor(product)) return; const container = product.requires_container_choice ? this.containerType : null; const existing = this.cart.find(item => item.product_id === product.id && item.container_type === container); if (existing) existing.quantity++; else this.cart.push({ ...product, product_id: product.id, container_type: container, quantity: 1 }); }, removeFromCart(index) { this.cart.splice(index, 1); }, increment(index) { if (this.cartQuantity(this.cart[index].product_id, this.cart[index].container_type) < this.stockFor(this.cart[index], this.cart[index].container_type)) this.cart[index].quantity++; }, decrement(index) { if (this.cart[index].quantity > 1) this.cart[index].quantity--; }, itemTotal(item) { return Number(item.unit_price) * item.quantity; }, get subtotal() { return this.cart.reduce((sum, item) => sum + this.itemTotal(item), 0); }, get gallonCount() { return this.cart.filter(item => item.requires_container_choice).reduce((sum, item) => sum + item.quantity, 0); }, get deliveryFee() { return Math.round(this.feeRate * this.gallonCount * 100) / 100; }, get total() { return this.subtotal + this.deliveryFee; } }; }</script>@endpush
</x-layouts.app>
